import{_ as l,o as a,c as e,a2 as r}from"./chunks/framework.CZGNF-7T.js";const u=JSON.parse('{"title":"영업 조직 관리","description":"","frontmatter":{},"headers":[],"relativePath":"sales/organization.md","filePath":"sales/organization.md","lastUpdated":1788696788000}'),i={name:"sales/organization.md"};function t(n,o,s,d,c,g){return a(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="영업-조직-관리" tabindex="-1">영업 조직 관리 <a class="header-anchor" href="#영업-조직-관리" aria-label="Permalink to &quot;영업 조직 관리&quot;">​</a></h1><p>프로젝트에 투입되는 분양 대행사, 영업 본부/팀, 그리고 영업 상담사 및 팀장 등 인력을 3단계 계층 구조로 등록하고 계좌 정보와 3.3% 프리랜서 과세 유형을 관리하는 기준 정보 페이지입니다.</p><ul><li><strong>위치</strong>: <code>PJT 관리 시스템 &gt; 분양 대행 관리 &gt; 영업 조직 관리</code></li></ul><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>분양 영업을 전담하는 조직 체계를 체계적으로 전산화합니다. 분양 대행사(<code>SalesAgency</code>)를 최상위로 두고 그 산하에 영업 본부 및 팀(<code>SalesTeam</code>)을 트리 형태로 구성하며, 각 팀에 소속되는 상담사 및 팀장(<code>SalesPerson</code>)을 등록합니다. 특히 수수료 이체 및 원천징수 신고를 위해 각 인력별 금융 계좌 정보와 과세 유형(3.3% 사업소득 프리랜서 여부)을 철저히 관리합니다.</p><h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>3단계 영업 조직 계층 관리</strong>: 대행사 ➔ 영업 본부/팀 ➔ 영업 인력(상담사)</li><li><strong>좌측 조직 트리뷰 연동</strong>: 대행사 또는 팀 선택 시 우측 명부에 해당 소속 인력만 즉시 필터링</li><li><strong>대행사 운영 형태 구분</strong>: 본사 직영 조직 또는 외부 전문 분양대행사 구분 관리</li><li><strong>프리랜서(3.3%) 세무 유형 설정</strong>: 사업소득세 원천징수 대상자 여부 등록</li><li><strong>금융 입금 계좌 관리</strong>: 주요 시중은행, 인터넷은행, 지방은행 셀렉터 및 계좌번호, 예금주 등록</li><li><strong>재직 상태 관리</strong>: 위촉, 재직, 휴직, 해촉(퇴사) 상태 관리</li></ul><h2 id="화면-구성" tabindex="-1">화면 구성 <a class="header-anchor" href="#화면-구성" aria-label="Permalink to &quot;화면 구성&quot;">​</a></h2><h3 id="_1-좌측-영업-조직-계층-트리뷰-agencyteamtree" tabindex="-1">1. 좌측 영업 조직 계층 트리뷰 (AgencyTeamTree) <a class="header-anchor" href="#_1-좌측-영업-조직-계층-트리뷰-agencyteamtree" aria-label="Permalink to &quot;1. 좌측 영업 조직 계층 트리뷰 (AgencyTeamTree)&quot;">​</a></h3><p>프로젝트에 등록된 대행사와 산하 팀 구조를 한눈에 볼 수 있는 트리 뷰입니다.</p><ul><li><strong>[대행사 추가] 버튼</strong>: 상단 <code>+</code> 버튼으로 신규 대행사 등록</li><li><strong>대행사 아이템</strong>: <ul><li>직영/외주 뱃지 표출</li><li>수정(<code>[연필]</code>), 삭제(<code>[휴지통]</code>), 하위 팀 추가(<code>[+]</code>) 버튼 제공</li></ul></li><li><strong>하위 팀 아이템</strong>: <ul><li>팀 소속 인원수 뱃지 표출</li><li>클릭 시 해당 팀이 강조 표시되며 우측 인력 명부가 자동 필터링</li><li>수정 및 삭제 버튼 제공</li></ul></li></ul><h3 id="_2-우측-영업-인력-명부-personlist" tabindex="-1">2. 우측 영업 인력 명부 (PersonList) <a class="header-anchor" href="#_2-우측-영업-인력-명부-personlist" aria-label="Permalink to &quot;2. 우측 영업 인력 명부 (PersonList)&quot;">​</a></h3><p>선택된 대행사 또는 팀에 소속된 영업 인력의 상세 명단 테이블입니다.</p><ul><li><strong>상단 필터 및 제어 바</strong>: <ul><li>재직 상태 필터 (전체, 위촉, 재직, 휴직, 해촉)</li><li>과세 유형 필터 (전체, 3.3% 사업소득, 근로소득)</li><li>성명/연락처 검색창</li><li><code>[영업 인력 등록]</code> 버튼 (<code>primary</code>)</li></ul></li><li><strong>인력 목록 테이블</strong>: <ul><li>소속 대행사 및 팀</li><li>성명, 직책 (상담사, 팀장, 본부장, 총괄)</li><li>연락처, 이메일</li><li>과세 유형 (3.3% 프리랜서 뱃지)</li><li>입금 계좌 정보 (은행명 및 계좌번호, 예금주)</li><li>재직 상태 (정상, 휴직, 해촉 뱃지)</li><li>행별 수정(<code>[연필]</code>) 및 삭제(<code>[휴지통]</code>) 버튼</li></ul></li></ul><h3 id="_3-입력-폼-모달-안내" tabindex="-1">3. 입력 폼 모달 안내 <a class="header-anchor" href="#_3-입력-폼-모달-안내" aria-label="Permalink to &quot;3. 입력 폼 모달 안내&quot;">​</a></h3><h4 id="_1-대행사-등록-모달-agencyformmodal" tabindex="-1">① 대행사 등록 모달 (AgencyFormModal) <a class="header-anchor" href="#_1-대행사-등록-모달-agencyformmodal" aria-label="Permalink to &quot;① 대행사 등록 모달 (AgencyFormModal)&quot;">​</a></h4><ul><li><strong>대행사명</strong> (필수): 회사 상호 또는 직영 사업단 명칭</li><li><strong>운영 형태</strong>: 직영 분양팀 또는 외주 대행사 선택</li><li><strong>대표자명 / 사업자등록번호 / 연락처 / 담당자 정보</strong></li><li><strong>계약 기간</strong>: 대행 계약 시작일 및 종료일 (<code>DatePicker</code>)</li></ul><h4 id="_2-영업-팀-등록-모달-teamformmodal" tabindex="-1">② 영업 팀 등록 모달 (TeamFormModal) <a class="header-anchor" href="#_2-영업-팀-등록-모달-teamformmodal" aria-label="Permalink to &quot;② 영업 팀 등록 모달 (TeamFormModal)&quot;">​</a></h4><ul><li><strong>소속 대행사</strong> (필수): 소속될 상위 대행사 선택</li><li><strong>상위 조직</strong>: 본부 산하 팀 구성 시 상위 본부 선택 (다단계 계층 지원)</li><li><strong>팀/조직명</strong> (필수): 예: &quot;분양 1본부&quot;, &quot;영업 2팀&quot;</li><li><strong>팀장 성명</strong>: 조직 책임자 성명</li></ul><h4 id="_3-영업-인력-등록-모달-personformmodal" tabindex="-1">③ 영업 인력 등록 모달 (PersonFormModal) <a class="header-anchor" href="#_3-영업-인력-등록-모달-personformmodal" aria-label="Permalink to &quot;③ 영업 인력 등록 모달 (PersonFormModal)&quot;">​</a></h4><ul><li><strong>소속 팀</strong> (필수): 배치될 영업 팀 선택</li><li><strong>성명</strong> (필수) 및 <strong>직책</strong> (상담사, 팀장, 본부장, 총괄본부장)</li><li><strong>휴대전화</strong> (필수) 및 <strong>주민등록번호</strong> (원천세 신고용)</li><li><strong>과세 유형</strong> (필수): <code>3.3% 사업소득 (프리랜서)</code> 또는 <code>근로소득 (4대보험)</code></li><li><strong>금융 계좌 정보</strong>: 거래 은행 선택, 계좌번호, 예금주명</li><li><strong>위촉일 / 해촉일</strong>: 위촉(입사)일자 및 해촉(퇴사)일자 (<code>DatePicker</code>)</li><li><strong>비고</strong>: 추천인, 영업 경력 사항 등 메모</li></ul>',21)])])}const m=l(i,[["render",t]]);export{u as __pageData,m as default};
